def read_between(low, high):
    while True:
        try:
            raw = input(f"Whole number {low}..{high}, or cancel: ")
        except EOFError:
            return None
        if raw.strip().lower() == "cancel":
            return None
        try:
            value = int(raw)
        except ValueError:
            print("Enter a whole number")
            continue
        if low <= value <= high:
            return value
        print(f"Use {low} through {high}")
